INSERT OR IGNORE INTO `settings` (`key`, `value`, `updated_at`) VALUES ('weekendBox', '{"title":"The weekend box","priceCents":3200,"blurb":"Everything for a slow Saturday or Sunday morning, packed up and waiting for you. Reserve ahead, skip the line, and pay when you pick it up.","items":["One sourdough loaf","Two butter croissants","Two cinnamon rolls","A jar of cultured butter","A jar of seasonal jam","Half a pound of house coffee"]}', 1793491200);
